const fs = require("fs");
function symptom(msg) { console.error("FAIL: " + msg); process.exit(1); }
function broken(msg) { console.error("ERROR: " + msg); process.exit(2); }
(async () => {
  const tw = require("tailwindcss");
  if (typeof tw.__unstable__loadDesignSystem !== "function") broken("__unstable__loadDesignSystem is missing");
  const file = "/w/node_modules/tailwindcss/index.css";
  const ds = await tw.__unstable__loadDesignSystem('@import "tailwindcss";', {
    base: "/tmp",
    loadStylesheet: async (id, base) => {
      if (id !== "tailwindcss") broken("unexpected stylesheet " + id);
      return { path: file, base: "/w/node_modules/tailwindcss", content: fs.readFileSync(file, "utf8") };
    },
  });
  if (typeof ds.canonicalizeCandidates !== "function") broken("canonicalizeCandidates is missing");
  const ctl = ds.canonicalizeCandidates(["mt-1", "mb-1"], { collapse: true });
  if (JSON.stringify(ctl) !== JSON.stringify(["my-1"])) broken("control mt-1 mb-1 gave " + JSON.stringify(ctl));
  const got = ds.canonicalizeCandidates(["overflow-x-hidden", "overflow-y-hidden"], { collapse: true });
  if (JSON.stringify(got) === JSON.stringify(["overflow-hidden"])) { console.log("OK: overflow-x-hidden overflow-y-hidden collapse into overflow-hidden"); return; }
  if (got.length === 2 && got.includes("overflow-x-hidden") && got.includes("overflow-y-hidden")) symptom("overflow-x-hidden overflow-y-hidden are not collapsed into overflow-hidden");
  broken("unexpected result " + JSON.stringify(got));
})().catch((e) => broken(String((e && e.stack) || e)));

